const SUPABASE_URL = process.env.SUPABASE_URL || 'https://tu-proyecto.supabase.co';
const SUPABASE_ANON_KEY = process.env.SUPABASE_ANON_KEY || 'tu-anon-key';

// Initialize only if keys actally exist (to avoid crashing the demo)
export const supabase = (SUPABASE_URL !== 'https://tu-proyecto.supabase.co') 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY)
  : null;

// Helper to check if we are online/connected to DB
export const isDbConnected = () => !!supabase;

