interface OnboardingModalProps {
  onComplete: (user: User) => void;
  onClose: () => void;
  initialStep?: number; // Allow jumping to step 3 if coming back from Stripe
}

export const OnboardingModal: React.FC<OnboardingModalProps> = ({ onComplete, onClose, initialStep = 1 }) => {
  const [step, setStep] = useState(initialStep);
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isRegistering, setIsRegistering] = useState(false);

  // Form State
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const handleNext = () => {
    if (step === 1 && acceptedTerms) setStep(2);
  };

  const handlePay = () => {
    setIsLoading(true);

    // Check if link is configured (not the default placeholder)
    if (config.stripePaymentLink.includes("test_") || config.stripePaymentLink.length < 20) {
        // DEMO MODE / FALLBACK
        console.warn("Stripe Link not fully configured in config.ts, running simulation.");
        setTimeout(() => {
            setIsLoading(false);
            setStep(3);
        }, 1500);
    } else {
        // REAL MODE
        window.location.href = config.stripePaymentLink;
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (name && password) {
      setIsRegistering(true);

      try {
        let userId = undefined;

        // Sync to Supabase if connected
        if (supabase) {
           const { data, error } = await supabase
             .from('cases')
             .insert([{ username: name, password: password, status: 'analyzing' }])
             .select()
             .single();

           if (error) {
             console.error("Supabase Error:", error);
             // If error is duplicate user, we might want to alert, but for MVP we proceed locally or alert
             if (error.code === '23505') {
                 alert("Este nombre de usuario ya existe. Por favor elige otro.");
                 setIsRegistering(false);
                 return;
             }
           } else if (data) {
             userId = data.id;
           }
        }

        onComplete({ id: userId, name, password });
      } catch (err) {
        console.error("Registration error", err);
        // Fallback to local
        onComplete({ name, password });
      }
    }
  };

  return (
