import React, { useState } from 'react';
import { X, Lock, Eye, EyeOff, AlertCircle, ArrowRight, User as UserIcon, Loader2 } from 'lucide-react';
import { Logo } from './Logo';
import { User } from '../types';
import { supabase } from '../services/supabaseClient';

interface LoginModalProps {
  onSuccess: (user: User) => void;
  onClose: () => void;
}

export const LoginModal: React.FC<LoginModalProps> = ({ onSuccess, onClose }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
        let authenticatedUser: User | null = null;

        // 1. Try Supabase Login (Cloud)
        if (supabase) {
            const { data, error: dbError } = await supabase
                .from('cases')
                .select('*')
                .eq('username', username)
                .eq('password', password)
                .single();

            if (data) {
                authenticatedUser = {
                    id: data.id,
                    name: data.username,
                    password: data.password
                };
            } else if (dbError && dbError.code !== 'PGRST116') {
                 // Real DB error (not just "row not found")
                 console.error("DB Login Error:", dbError);
            }
        }

        // 2. Fallback to LocalStorage (Legacy/Offline support)
        if (!authenticatedUser) {
            const storedUserJson = localStorage.getItem('justino_user');
            if (storedUserJson) {
                const storedUser: User = JSON.parse(storedUserJson);
                // Match local storage format which was only password in previous iterations, 
                // but now we expect user to know their username.
                // Simple check: if password matches and (name matches OR we just rely on password for legacy)
                if (storedUser.password === password && storedUser.name === username) {
                    authenticatedUser = storedUser;
                }
            }
        }

        if (authenticatedUser) {
            onSuccess(authenticatedUser);
        } else {
            setError('Usuario o contraseña incorrectos.');
        }

    } catch (err) {
        console.error(err);
        setError('Error de conexión. Intenta nuevamente.');
    } finally {
        setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-navy-900/90 backdrop-blur-md">
      <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden relative animate-fade-in-up">
        {/* Header */}
        <div className="bg-navy-900 p-6 flex justify-between items-center text-white">
          <div className="flex items-center gap-2">
            <Logo className="w-6 h-6 text-emerald-500" />
            <span className="font-bold">Acceso Seguro</span>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white">
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Content */}
        <div className="p-8">
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-navy-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-navy-100">
              <Lock className="w-8 h-8 text-navy-900" />
            </div>
            <h2 className="text-2xl font-bold text-navy-900">Bienvenido de nuevo</h2>
            <p className="text-slate-500 mt-2">Accede a tu caso desde cualquier dispositivo.</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Nombre de Usuario</label>
              <div className="relative">
                <input 
                  type="text" 
                  required
                  autoFocus
                  value={username}
                  onChange={(e) => {
                    setUsername(e.target.value);
                    setError('');
                  }}
                  className="w-full p-4 pr-12 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:outline-none transition-shadow text-lg"
                  placeholder="Tu usuario"
                />
                <UserIcon className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Contraseña</label>
              <div className="relative">
                <input 
                  type={showPassword ? "text" : "password"} 
                  required
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    setError('');
                  }}
                  className="w-full p-4 pr-12 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:outline-none transition-shadow text-lg"
                  placeholder="••••••••"
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 focus:outline-none"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>

            {error && (
              <div className="flex items-center gap-2 text-red-600 text-sm bg-red-50 p-3 rounded-lg border border-red-100 animate-pulse-fast">
                <AlertCircle className="w-4 h-4" />
                {error}
              </div>
            )}

            <button 
              type="submit"
              disabled={isLoading}
              className="w-full py-4 bg-navy-900 text-white rounded-xl font-bold shadow-lg hover:bg-navy-800 transition-all flex items-center justify-center gap-2 group disabled:opacity-70"
            >
              {isLoading ? (
                  <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                  <>
                    Abrir Expediente
                    <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                  </>
              )}
            </button>
          </form>

          <div className="mt-6 text-center">
             <p className="text-xs text-slate-400">
               Tus datos están encriptados en la nube de Justino.
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LandingPage } from './components/LandingPage';
import { OnboardingModal } from './components/OnboardingModal';
import { Dashboard } from './components/Dashboard';
import { LoginModal } from './components/LoginModal';
import { AdminLogin } from './components/AdminLogin';
import { AdminDashboard } from './components/AdminDashboard';
import { User, AppView, Message, VaultFile } from './types';
import { supabase } from './services/supabaseClient';

function App() {
  const [view, setView] = useState<AppView>('landing');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(1); // Default step 1

  const [user, setUser] = useState<User | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [vaultFiles, setVaultFiles] = useState<VaultFile[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);

  // 1. Session & URL Params Check
  useEffect(() => {
    // Check URL parameters (Return from Stripe)
    const urlParams = new URLSearchParams(window.location.search);
    const success = urlParams.get('success');

    if (success === 'true') {
        // Stripe returned success -> Open Onboarding at Step 3 (Account Creation)
        setView('onboarding');
        setOnboardingStep(3);
        // Clean URL
        window.history.replaceState({}, document.title, window.location.pathname);
    } else {
        // Normal Session Check
        const isSessionActive = sessionStorage.getItem('justino_session_active');
        const savedUser = localStorage.getItem('justino_user');

        if (isSessionActive && savedUser) {
          const parsedUser = JSON.parse(savedUser);
          setUser(parsedUser);
          setView('dashboard');
          // We trigger loadMessages inside a separate effect that watches 'user'
        }

        // Admin Check
        const isAdminActive = sessionStorage.getItem('justino_admin_active');
        if (isAdminActive) {
            setView('admin-dashboard');
        }
    }
  }, []);

  // 2. Load Data (Cloud + Local Merge)
  useEffect(() => {
    if (user && view === 'dashboard') {
        // Local Sync
        localStorage.setItem('justino_user', JSON.stringify(user));

        // Cloud Fetch
        const fetchCloudData = async () => {
            if (!supabase || !user.id) {
                // Fallback to local if no cloud ID or no connection
                loadLocalData();
                return;
            }

            setIsSyncing(true);
            try {
                // Fetch Messages
                const { data: msgs, error: msgError } = await supabase
                    .from('messages')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('timestamp', { ascending: true });

                if (msgs && !msgError) {
                    const formattedMessages: Message[] = msgs.map(m => ({
                        id: m.id,
                        text: m.text,
                        sender: m.sender,
                        timestamp: new Date(m.timestamp),
                        attachment: m.attachment || undefined
                    }));
                    setMessages(formattedMessages);
                    // Also update local storage for offline backup
                    localStorage.setItem('justino_messages', JSON.stringify(formattedMessages));
                }

                // Fetch Files
                const { data: files, error: fileError } = await supabase
                    .from('documents')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('created_at', { ascending: false });

                if (files && !fileError) {
                    const formattedFiles: VaultFile[] = files.map(f => ({
                        id: f.id,
                        name: f.name,
                        type: f.type,
                        content: f.content,
                        origin: f.origin as 'generated' | 'uploaded',
                        date: f.created_at
                    }));
                    setVaultFiles(formattedFiles);
                    localStorage.setItem('justino_vault', JSON.stringify(formattedFiles));
                }

            } catch (e) {
                console.error("Sync Error", e);
                loadLocalData();
            } finally {
                setIsSyncing(false);
            }
        };

        fetchCloudData();
    }
  }, [user, view]);

  const loadLocalData = () => {
    const savedMessages = localStorage.getItem('justino_messages');
    if (savedMessages) {
      const parsed = JSON.parse(savedMessages);
      setMessages(parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })));
    }

    const savedFiles = localStorage.getItem('justino_vault');
    if (savedFiles) {
      setVaultFiles(JSON.parse(savedFiles));
    }
  };

  const handleStart = () => {
    const savedUser = localStorage.getItem('justino_user');
    if (savedUser) {
      setShowLoginModal(true);
    } else {
      setView('onboarding');
      setOnboardingStep(1);
    }
  };

  const cancelOnboarding = () => {
    setView('landing');
    setOnboardingStep(1);
  };

  const cancelLogin = () => {
    setShowLoginModal(false);
  };

  const handleLoginSuccess = (loggedInUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(loggedInUser);
    setShowLoginModal(false);
    setView('dashboard');
  };

  const completeOnboarding = async (newUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = () => {
    sessionStorage.removeItem('justino_session_active');
    setUser(null);
    setMessages([]);
    setVaultFiles([]);
    setView('landing');
  };

  const handleNewMessage = async (msg: Message) => {
    // 1. Optimistic UI Update
    setMessages(prev => [...prev, msg]);

    // 2. Cloud Save
    if (supabase && user?.id) {
        try {
            await supabase.from('messages').insert([{
                id: msg.id,
                case_id: user.id,
                text: msg.text,
                sender: msg.sender,
                timestamp: msg.timestamp.toISOString(),
                attachment: msg.attachment ? msg.attachment : null
            }]);
        } catch (e) {
            console.error("Failed to save message to cloud", e);
        }
    }

    // 3. Local Backup
    const currentMsgs = [...messages, msg];
    localStorage.setItem('justino_messages', JSON.stringify(currentMsgs));
  };

  const handleAddFile = async (name: string, type: string, content: string, origin: 'generated' | 'uploaded' = 'generated') => {
    const newFile: VaultFile = {
      id: Date.now().toString(),
      name,
      type,
      date: new Date().toISOString(),
      content,
      origin
    };

    // 1. Optimistic UI
    setVaultFiles(prev => [newFile, ...prev]);

    // 2. Cloud Save
    if (supabase && user?.id) {
        try {
            await supabase.from('documents').insert([{
                id: newFile.id,
                case_id: user.id,
                name,
                type,
                content, // Storing base64 text directly in DB for simplicity of this MVP
                origin,
                created_at: newFile.date
            }]);
        } catch (e) {
            console.error("Failed to save file to cloud", e);
        }
    }

    // 3. Local Backup
    const currentFiles = [newFile, ...vaultFiles];
    localStorage.setItem('justino_vault', JSON.stringify(currentFiles));
  };

  // --- ADMIN LOGIC ---
  const handleAdminAccess = () => {
      setView('admin-login');
  };

  const handleAdminLoginSuccess = () => {
      sessionStorage.setItem('justino_admin_active', 'true');
      setView('admin-dashboard');
  };

  const handleAdminLogout = () => {
      sessionStorage.removeItem('justino_admin_active');
      setView('landing');
  };

  const hasExistingSession = !!localStorage.getItem('justino_user');

  return (
    <>
      {view === 'landing' && (
        <LandingPage 
            onStart={handleStart} 
            onAdminAccess={handleAdminAccess} 
            hasExistingSession={hasExistingSession} 
        />
      )}

      {showLoginModal && (
        <LoginModal onSuccess={handleLoginSuccess} onClose={cancelLogin} />
      )}

      {view === 'onboarding' && (
        <>
          <LandingPage onStart={() => {}} onAdminAccess={() => {}} hasExistingSession={hasExistingSession} /> 
          <OnboardingModal 
            onComplete={completeOnboarding} 
            onClose={cancelOnboarding} 
            initialStep={onboardingStep}
          />
        </>
      )}

      {view === 'dashboard' && user && (
        <Dashboard 
          user={user} 
          messages={messages} 
          vaultFiles={vaultFiles}
          onNewMessage={handleNewMessage}
          onAddFile={handleAddFile}
          onLogout={handleLogout}
        />
      )}

      {/* Admin Views */}
      {view === 'admin-login' && (
          <AdminLogin onSuccess={handleAdminLoginSuccess} onClose={() => setView('landing')} />
      )}

      {view === 'admin-dashboard' && (
          <AdminDashboard onLogout={handleAdminLogout} />
      )}
    </>
  );
}

export default App;

import React from 'react';

interface LogoProps {
  className?: string;
  color?: string; // Kept for compatibility, though we prioritize the gradient now
}

export const Logo: React.FC<LogoProps> = ({ className = "w-8 h-8", color }) => {
  // Generate a unique ID for the gradient to avoid conflicts if multiple logos exist
  const gradientId = React.useId(); 

  return (
    <svg 
      xmlns="http://www.w3.org/2000/svg" 
      viewBox="0 0 100 100" 
      className={className} 
      fill="none"
    >
      <defs>
        {/* The Emerald Gradient: Represents 'Digital Hope' */}
        <linearGradient id={`${gradientId}-emerald`} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#34D399" /> {/* Emerald 400 (Bright) */}
          <stop offset="100%" stopColor="#065F46" /> {/* Emerald 800 (Deep) */}
        </linearGradient>

        {/* Subtle inner glow for 3D effect */}
        <filter id={`${gradientId}-glow`} x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur stdDeviation="2" result="blur" />
          <feComposite in="SourceGraphic" in2="blur" operator="over" />
        </filter>
      </defs>

      {/* 
        THE SHAPE: "The Justino Node"
        It's a hexagon representing structure/law.
        Inside, a dynamic path cuts through, forming an abstract 'J' 
        that looks like a circuit connection.
      */}
      <g filter={`url(#${gradientId}-glow)`}>
        {/* Main Body */}
        <path 
          d="M50 5 L93.3 30 V80 L50 105 L6.7 80 V30 Z" 
          fill={`url(#${gradientId}-emerald)`} 
          transform="scale(0.85) translate(8, 0)" // Adjust positioning
        />

        {/* The 'J' Cutout / Circuit Path (Negative Space) */}
        <path 
          d="M50 35 V65 C50 70.5 45.5 75 40 75 H35 V60 H40 V45 H30 V75 C30 83.3 36.7 90 45 90 H55 C63.3 90 70 83.3 70 75 V35 H50 Z" 
          fill="white" 
          fillOpacity="0.95"
        />

        {/* The 'Dot' / Spark of AI (Top Right) */}
        <circle cx="70" cy="35" r="7" fill="white" fillOpacity="0.95" />
      </g>
    </svg>
  );
};

